uc(0,'UC-AUTH-01','Đăng ký và xác minh tài khoản','Người dùng chưa đăng nhập; dịch vụ email','Có danh tính chủ workspace đã xác minh.','Chọn Đăng ký.','Chưa có phiên owner; kênh xác minh khả dụng.',[
'Người dùng nhập email, mật khẩu và xác nhận mật khẩu.','Hệ thống kiểm tra dữ liệu, tạo yêu cầu xác minh và gửi mã qua kênh email.','Người dùng nhập mã; hệ thống kiểm thời hạn, số lần thử và mục đích mã.','Hệ thống hoàn tất danh tính/phiên theo giao thức và dẫn tới tạo hoặc chọn workspace.'
],['Email đã tồn tại: phản hồi theo chính sách chống dò tài khoản.','Mã sai/hết hạn hoặc gửi quá nhiều: cho thử lại/gửi lại trong giới hạn; không mở phiên đã xác minh.','Email thực chưa cấu hình: báo chưa thể hoàn tất; mail sink local chỉ là công cụ thử.'],'Danh tính hợp lệ được tạo; chưa có tài khoản tiền hoặc bút toán do đăng ký.','REQ-SURFACE-01; SRS NFR identity; identity-access-design.md');
uc(0,'UC-AUTH-02','Đăng nhập chủ workspace','Chủ workspace; dịch vụ email','Truy cập đúng workspace bằng danh tính hợp lệ.','Chọn Đăng nhập.','Danh tính đã đăng ký; browser/native dùng đúng loại credential.',[
'Chủ workspace nhập thông tin đăng nhập.','Hệ thống kiểm credential và yêu cầu challenge theo giao thức/kênh hiện hành.','Người dùng hoàn tất challenge; hệ thống cấp phiên có phạm vi.','Người dùng chọn workspace; hệ thống tải dữ liệu được phép và phiên bản hiện hành.'
],['Sai thông tin, khóa/tạm chặn hoặc challenge hết hạn: không cấp phiên.','Thiết bị native chưa chứng minh danh tính: không dùng đăng nhập demo thay enrollment.','Chưa có workspace: chuyển UC-SET-01; không tự đọc workspace khác.'],'Phiên owner có hiệu lực đúng phạm vi; không thay đổi số dư.','REQ-SURFACE-01 / AC-29; identity-access-design.md');
uc(0,'UC-AUTH-03','Khôi phục mật khẩu','Chủ tài khoản; dịch vụ email','Khôi phục truy cập qua kênh đã xác minh.','Chọn Quên mật khẩu.','Có email tiếp nhận yêu cầu; không yêu cầu phiên đang đăng nhập.',[
'Người dùng gửi yêu cầu khôi phục bằng email.','Hệ thống phản hồi theo chính sách chống dò và phát challenge có thời hạn nếu phù hợp.','Người dùng cung cấp mã/token và mật khẩu mới.','Hệ thống xác minh mục đích, cập nhật credential, thu hồi phiên theo chính sách và yêu cầu đăng nhập lại.'
],['Token sai, hết hạn hoặc dùng lại: từ chối; không đổi mật khẩu.','Không truy cập được email: áp dụng recovery protocol được duyệt; app-admin không được tự nhập vai owner.'],'Mật khẩu đổi một lần khi hợp lệ; credential cũ bị xử lý đúng chính sách.','identity-access-design.md; NFR-07/19');
uc(0,'UC-AUTH-04','Quản lý phiên, thiết bị và đăng xuất','Chủ workspace','Kiểm soát nơi đang truy cập và thu hồi quyền.','Mở Phiên/Thiết bị hoặc chọn Đăng xuất.','Có phiên hợp lệ; thao tác nhạy cảm có thể cần xác thực lại.',[
'Hệ thống liệt kê phiên và thiết bị của chính người dùng với metadata tối thiểu.','Người dùng chọn đăng xuất, thu hồi phiên hoặc thu hồi thiết bị.','Hệ thống yêu cầu xác nhận/xác thực lại nếu cần và thu hồi credential tương ứng.','Client xóa cache nhạy cảm và dừng tác vụ mới; hàng đợi native không được chuyển sang owner khác.'
],['Thiết bị offline: server vẫn chặn lần truy cập sau; không khẳng định đã xóa vật lý dữ liệu ở thiết bị.','Thu hồi phiên hiện tại: điều hướng về đăng nhập.','Timeout: kiểm tra kết quả trước khi phát yêu cầu mới.'],'Quyền bị thu hồi đúng phạm vi; lịch sử tài chính vẫn tồn tại.','REQ-SURFACE-01 / AC-29; REQ-SYNC-01 / AC-33');
uc(1,'UC-SET-01','Thiết lập mốc theo dõi và thông số','Chủ workspace','Thiết lập mốc, tiền tệ và múi giờ nhất quán.','Khởi tạo workspace hoặc mở Thiết lập.','Phiên owner hợp lệ; scope workspace rõ.',[
'Hệ thống hiển thị mốc theo dõi, VND và múi giờ nghiệp vụ.','Người dùng nhập mốc theo dõi và thông số được hỗ trợ.','Hệ thống kiểm hợp lệ, giải thích số dư đầu kỳ khác thu nhập; nếu đã có dữ liệu thì xem trước tác động.','Người dùng xác nhận; hệ thống lưu phiên bản thiết lập và áp dụng cùng mốc cho các màn hình.'
],['Mốc sai hoặc không được hỗ trợ: giữ nhập liệu và chỉ rõ lỗi.','Đổi mốc sau khi có dữ liệu: không tự ghi thêm opening; cần kiểm tác động trước xác nhận.'],'Workspace có cấu hình phiên bản mới; không sinh thu nhập.','REQ-SET-01 / AC-01','BR-01/03/04/19; CF-01…05');
uc(1,'UC-BANK-01','Tạo và quản lý tài khoản ngân hàng/ví','Chủ workspace','Theo dõi từng tài khoản tiền độc lập.','Chọn Thêm/Sửa tài khoản ngân hàng hoặc ví.','Đã có workspace và mốc; nguồn tiền thuộc owner.',[
'Người dùng chọn loại ngân hàng/ví, nhập tên và thông tin định danh cần thiết.','Người dùng khai báo số dư đầu kỳ và ngày, hoặc chọn chưa biết số dư.','Hệ thống kiểm dữ liệu, hiển thị nguồn tự khai báo và tác động opening.','Người dùng xác nhận; hệ thống lưu tài khoản và opening hợp lệ trong một giao dịch; sửa metadata giữ lịch sử.'
],['Bỏ số dư: lưu unknown, không coi bằng 0.','Số 0 được nhập rõ là số dư đã khai báo; không bắt tạo ledger line bằng 0.','Trùng tên: cảnh báo, không tự gộp; đổi opening đã ghi phải qua quy trình điều chỉnh có dấu vết.'],'Tài khoản có ID riêng; opening chỉ có hiệu lực một lần và không là income.','REQ-BANK-01 / AC-02','BR-02/04/09/20/45');
uc(1,'UC-CASH-01','Tạo và quản lý ví tiền mặt','Chủ workspace','Theo dõi tiền mặt tự khai báo tách khỏi kiểm đếm.','Chọn Thêm/Sửa ví tiền mặt.','Workspace và mốc đã thiết lập.',[
'Người dùng nhập tên ví, ngày và số dư tự khai báo hoặc trạng thái chưa biết.','Hệ thống kiểm dữ liệu và xem trước số dư đầu kỳ.','Người dùng xác nhận; hệ thống tạo ví cùng opening hợp lệ.','Hệ thống hiển thị số tính toán và trạng thái chưa kiểm đếm riêng.'
],['Số dư chưa biết: không tổng hợp thành số 0 đã xác minh.','Sửa tên không đổi tiền; bổ sung opening cần kiểm phiên bản và ghi một lần.'],'Ví tiền mặt có nguồn tự khai báo; chưa có observation kiểm đếm.','REQ-CASH-01 / AC-03','BR-02/04/14/45');
uc(1,'UC-CASH-02','Kiểm đếm và đối soát tiền mặt','Chủ workspace','Phát hiện chênh lệch giữa số đếm và số tính cùng thời điểm.','Chọn Kiểm đếm tiền mặt.','Ví active; số tính có baseline và snapshot; thời điểm/đơn vị so sánh tương thích.',[
'Người dùng nhập số đếm và thời điểm kiểm đếm.','Hệ thống lưu observation và so với số tính tại cùng mốc.','Hệ thống hiển thị chênh lệch cùng căn cứ, chưa thay đổi ledger.','Người dùng kiểm tra nguyên nhân; nếu có khoản quên thì ghi qua UC-MONEY-01, hoặc lựa chọn điều chỉnh qua UC-CASH-03.'
],['Số đếm 0 hợp lệ.','Thiếu baseline hoặc lệch thời điểm: không đưa ra chênh lệch giả.','Chưa rõ nguyên nhân hoặc hủy xử lý: observation có thể giữ, tiền không tự đổi.'],'Có biên bản kiểm đếm; ledger chỉ đổi khi một thao tác ghi tiền riêng đã xác nhận.','REQ-CASH-02 / AC-09','BR-14/21');
uc(1,'UC-CASH-03','Xác nhận điều chỉnh chênh lệch tiền mặt','Chủ workspace','Ghi nhận chênh lệch chưa xác định nguyên nhân có dấu vết.','Trong UC-CASH-02, chọn Điều chỉnh.','Chênh lệch khác 0; observation/snapshot còn hợp lệ; có lý do.',[
'Hệ thống nêu số tính, số đếm, phần chênh lệch và loại adjustment.','Người dùng nhập lý do; hệ thống xem trước tác động tiền và thu–chi.','Người dùng xác nhận; hệ thống ghi adjustment, liên kết observation và audit atomically.','Hệ thống cập nhật snapshot và trạng thái case.'
],['Snapshot thay đổi: tính lại trước khi xác nhận.','Tìm ra khoản chi thật: chuyển ghi expense có căn cứ, tránh thêm cả expense lẫn adjustment.'],'Tiền điều chỉnh một lần; không tự quy thành thu nhập hay chi tiêu sinh hoạt.','Refinement REQ-CASH-02 / AC-09','BR-14/21/46');
uc(1,'UC-ACC-02','Lưu trữ và khôi phục tài khoản','Chủ workspace','Ngừng sử dụng tài khoản mà vẫn giữ lịch sử.','Chọn Lưu trữ/Khôi phục trong chi tiết tài khoản.','Tài khoản thuộc workspace; phiên bản hiện hành.',[
'Hệ thống hiển thị trạng thái, ảnh hưởng tới phạm vi và liên kết đang có.','Người dùng chọn lưu trữ hoặc khôi phục nếu chính sách cho phép.','Hệ thống xem trước và yêu cầu xác nhận.','Hệ thống đổi trạng thái, lưu history; tài khoản lưu trữ vẫn tra cứu trong phạm vi lịch sử.'
],['Liên kết hoặc nghiệp vụ còn mở: cảnh báo hoặc chặn theo quy tắc; không âm thầm xóa.','Lưu trữ không thay số dư bằng 0 và không xóa giao dịch.'],'Trạng thái tài khoản được cập nhật; lịch sử và căn cứ giữ nguyên.','Tách từ UC-DRILL-01 cũ; REQ-DRILL-01 / AC-14','BR-19/20');
uc(2,'UC-MONEY-01','Ghi giao dịch thu, chi, chuyển, hoàn và phí','Chủ workspace','Ghi biến động tiền đúng bản chất.','Chọn Thêm giao dịch.','Tài khoản active; workspace và VND hợp lệ; đủ căn cứ theo loại.',[
'Người dùng chọn loại, tài khoản, số tiền, ngày và thông tin liên quan.','Với chuyển khoản, chọn hai tài khoản khác nhau; với hoàn tiền, cung cấp giao dịch/căn cứ gốc.','Hệ thống kiểm dữ liệu và xem trước các bút toán, phí, tác động tiền và thu–chi.','Người dùng xác nhận; hệ thống ghi nhóm bút toán cân bằng cùng history/idempotency trong một transaction.','Hệ thống trả kết quả và cập nhật snapshot.'
],['Thiếu khoản gốc của refund: dùng trạng thái chưa giải quyết/Review theo policy; không tự coi income.','Transfer chỉ có một phía: dùng clearing và Review; không bịa chân còn lại.','Pending/draft không vào posted totals; phí là thành phần riêng đúng quy tắc.'],'Giao dịch được ghi một lần hoặc bị chặn rõ ràng; chuyển nội bộ không làm tăng tổng thu/chi.','REQ-MONEY-01 / AC-08','BR-01…13/45/46');
uc(2,'UC-TXN-01','Tra cứu và xem chi tiết giao dịch','Chủ workspace','Tìm giao dịch và đọc căn cứ đầy đủ.','Mở Giao dịch hoặc đi từ chỉ số báo cáo.','Có quyền đọc workspace; bộ lọc/phạm vi rõ.',[
'Người dùng chọn kỳ, tài khoản, loại, danh mục và trạng thái.','Hệ thống truy vấn theo snapshot và hiển thị kết quả cùng chất lượng dữ liệu.','Người dùng mở một giao dịch; hệ thống hiện loại, posting/reconciliation, nguồn, lịch sử và liên kết.','Người dùng quay lại; hệ thống giữ ngữ cảnh lọc và kỳ.'
],['Không có kết quả: hiển thị rỗng kèm cách đổi bộ lọc.','Lỗi truy vấn không được thay bằng danh sách rỗng; thiếu evidence phải có nhãn.'],'Chỉ đọc; không đổi số dư, giao dịch hoặc trạng thái đối soát.','REQ-TXN-01 / AC-11','BR-03/05/12/19/20');
uc(2,'UC-TXN-02','Sửa giao dịch và đảo bút toán đã ghi','Chủ workspace','Chỉnh sai có lịch sử và giữ bất biến ledger.','Chọn Sửa/Điều chỉnh ở giao dịch.','Đã tải giao dịch và version; posted correction có lý do.',[
'Hệ thống phân biệt draft, sửa metadata/danh mục và sửa tác động tài chính đã posted.','Người dùng sửa phần được phép và nhập lý do.','Hệ thống xem trước; posted correction tạo reversal/replacement thay vì sửa dòng ledger cũ.','Người dùng xác nhận; hệ thống lưu toàn bộ liên kết/history/tác động trong một transaction.','Hệ thống hiển thị bản gốc, bản đảo và bản thay thế.'
],['Giao dịch đã đảo: không đảo lần hai; mở replacement hiện hành.','Chỉ đổi danh mục: không thay tiền; nhập lại nguồn không xóa manual override.'],'Sửa đúng delta một lần; ledger sealed giữ nguyên.','REQ-TXN-02 / AC-12','BR-05/09/12/13/46');
uc(2,'UC-IMPORT-01','Nhập và đối soát sao kê CSV','Chủ workspace','Nhập phần giao dịch hợp lệ đã xem trước.','Chọn Nhập CSV.','Tài khoản đích active; file/profile được hỗ trợ; giới hạn theo cấu hình hiện hành.',[
'Người dùng chọn file và tài khoản; ánh xạ cột ngày, tiền, tham chiếu, nội dung và đơn vị tiền.','Hệ thống phân tích, giữ nguồn/parser/mapping, kiểm hợp lệ và phát hiện trùng.','Hệ thống hiển thị valid/invalid/duplicate/ambiguous và tác động; người dùng chọn các dòng hợp lệ.','Người dùng xác nhận; hệ thống ghi atomic tập được chọn và tạo Review cho phần cần xử lý theo policy.','Hệ thống trả job/result/history và cập nhật dữ liệu.'
],['CSV sai định dạng, vượt giới hạn hoặc số tiền mơ hồ: chặn hoặc chỉ rõ dòng lỗi trước commit.','Exact duplicate không ghi tiền lần hai; cùng amount chưa đủ kết luận trùng.','File/mapping/selection đổi làm preview cũ mất hiệu lực.'],'Các dòng hợp lệ đã chọn được ghi một lần hoặc không dòng nào; phần loại trừ không âm thầm posted.','REQ-INPUT-01 / AC-06','BR-09…12/21/42');
uc(2,'UC-CAPTURE-01','Cấp quyền và cấu hình thu thập thông báo','Chủ workspace; Android OS','Cho phép thu thập đúng nguồn trên đúng thiết bị.','Mở Kết nối thông báo Android.','APK hỗ trợ; owner/device được ràng buộc đúng; có source profile được hỗ trợ.',[
'Hệ thống giải thích dữ liệu thu, giới hạn coverage và nguồn hỗ trợ.','Người dùng đồng ý, chọn nguồn/tài khoản trong allowlist và cấp Notification Access qua Android.','Hệ thống kiểm consent, OS permission, binding, credential và profile.','Hệ thống hiển thị trạng thái sẵn sàng hoặc phần còn thiếu; người dùng có thể tắt/thu hồi.'
],['Deny/revoke hoặc thiếu enrollment: không báo đang thu thập đầy đủ.','Không nhận OTP/app ngoài allowlist; force-stop/gap được trình bày đúng.','Quyền phát notification thử và quyền đọc Notification Access là hai quyền khác nhau.'],'Chỉ capture khi tất cả điều kiện cho phép; cấp quyền không tự nhập lịch sử ngân hàng.','REQ-CAPTURE-01 / AC-31; REQ-APK-01 / AC-30','BR-42/43/44');
uc(2,'UC-INGEST-03','Tiếp nhận và chuẩn hóa thông báo tự động','Android OS và ứng dụng nguồn, qua collector FinWeave','Biến observation hợp lệ thành receipt/giao dịch hoặc case cần rà soát.','Thông báo của nguồn cho phép xuất hiện và được collector tiếp nhận.','Consent, binding và profile hợp lệ; local outbox/đồng bộ bảo đảm lưu bền.',[
'Collector kiểm nguồn và chính sách loại trừ trước khi đọc nội dung cần thiết.','Collector chuẩn hóa bằng parser version và lưu sự kiện vào outbox mã hóa.','Backend xác thực thiết bị, ghi durable receipt rồi mới ACK việc tiếp nhận.','Worker parse/validate, kiểm transport identity và semantic duplicate, tìm cặp transfer theo evidence.','Nếu đủ căn cứ, worker ghi ledger atomic; nếu chưa đủ, tạo Review và trả trạng thái xử lý rõ.'
],['Retry cùng eventId trả cùng receipt; hai giao dịch thật cùng amount không tự gộp.','Receipt ACK không đồng nghĩa đã posted; parser lỗi/thiếu căn cứ giữ chưa posted.','Thông báo có thể thiếu hoặc sai; không chứng minh balance hay coverage đầy đủ.'],'Receipt có truy vết; một sự kiện không nhân posting do gửi lại.','REQ-INGEST-03 / AC-32','BR-42/43/46');
uc(2,'UC-SYNC-01','Đồng bộ hàng đợi và dữ liệu đa thiết bị','Chủ workspace; collector trên Android','Đưa dữ liệu chưa gửi lên đúng owner và làm mới các giao diện.','Mạng trở lại, worker được lên lịch hoặc ứng dụng về foreground.','Queue có owner/device binding; credential chưa bị thu hồi.',[
'Native worker đọc các phần tử chưa được ACK thuộc binding hiện tại.','Worker gửi với event identity ổn định; server ghi durable receipt và trả ACK.','Native chỉ đánh dấu ACK khi xác nhận receipt đúng sự kiện.','Client đọc trạng thái/snapshot mới; không để phản hồi cũ đè phiên bản mới.','Sau restart, tiếp tục phần chưa được ACK và giữ kết quả đã biết.'
],['Offline/timeout: backoff và giữ queue; kết quả chưa rõ phải retry cùng identity.','Logout/revoke/đổi owner: chặn upload; không gửi queue A bằng credential B.','Gỡ app có thể làm mất queue local chưa sync; không cam kết tự phục hồi.'],'Queue được tiếp tục an toàn; các client hội tụ khi làm mới, không yêu cầu push realtime.','REQ-SYNC-01 / AC-33; REQ-RECOVERY-01 / AC-41','BR-42/44');
uc(2,'UC-SOURCE-01','Quản lý nguồn dữ liệu của workspace','Chủ workspace','Biết nguồn nào đang hoạt động và có thể cập nhật gì.','Mở Nguồn; chọn kết nối, cập nhật hoặc ngắt.','Có profile nguồn và quyền sử dụng phù hợp.',[
'Hệ thống hiện capability, trạng thái, lastAttempt, lastSuccess, coverage và dữ liệu cần cấp quyền.','Người dùng chọn nguồn/tài khoản, cung cấp thông tin cấu hình qua kênh được phép.','Hệ thống kiểm profile/entitlement và hiển thị connecting/processing khi chưa xong.','Kết quả đi qua pipeline notification hoặc quote phù hợp; hệ thống cập nhật trạng thái và căn cứ.','Người dùng ngắt nguồn; hệ thống dừng thu/lấy mới, giữ lịch sử có nhãn.'
],['Nguồn chưa được hỗ trợ hoặc chưa có quyền: không giả kết nối thành công.','Lỗi/429/revoked: giữ dữ liệu cũ với nhãn thời điểm; không về 0.'],'Cấu hình và trạng thái nguồn rõ; không tự sửa holdings chỉ do kết nối.','REQ-INPUT-02 / AC-07; REQ-CAPTURE-01/PRICE-01','BR-18/19/40…44');
uc(3,'UC-STOCK-01','Khai báo và quản lý danh mục cổ phiếu','Chủ workspace','Theo dõi lượng cổ phiếu và định giá có nguồn.','Chọn Thêm/Sửa cổ phiếu.','Workspace hợp lệ; catalog giải quyết được định danh mã/sàn.',[
'Người dùng chọn ticker và nhập quantity, ngày; giá vốn là tùy chọn.','Hệ thống resolve instrument/sàn/đơn vị và yêu cầu xác nhận nếu còn mơ hồ.','Hệ thống dùng quote phù hợp nếu có, hiện quantityAsOf và quoteAsOf riêng.','Người dùng xác nhận; hệ thống lưu khai báo/holding/history và hiển thị định giá.'
],['Không có quote: vẫn cho lưu khai báo hợp lệ, valuation unknown.','Thiếu giá vốn: P/L unknown, không coi cost=0.','Ticker trùng nhưng khác market: không tự gộp.'],'Holding được lưu; khai báo không tự tạo giao dịch tiền hoặc thu nhập.','REQ-STOCK-01/02 / AC-04/34','BR-15/18/19/22/40');
uc(3,'UC-GOLD-01','Khai báo và quản lý vàng','Chủ workspace','Định giá đúng sản phẩm và đổi đơn vị nhất quán.','Chọn Thêm/Sửa vàng hoặc đổi đơn vị hiển thị.','Gold profile gồm loại/tuổi/nguồn/side/unit được xác nhận.',[
'Người dùng chọn profile, nhập lượng theo đơn vị hỗ trợ, ngày và cost nếu biết.','Hệ thống kiểm profile và quy đổi quantity theo đơn vị chuẩn.','Hệ thống chọn quote tương thích và trình bày nguồn/thời điểm/đơn vị.','Người dùng xác nhận; hệ thống lưu holding/history và có thể đổi cách hiển thị chỉ/lượng.'
],['Quote khác product/purity/side/unit: không áp dụng.','Thiếu FX khi thực sự cần chuyển tiền tệ: valuation unknown hoặc partial có nhãn.','Đổi 2 chỉ thành 0,2 lượng không thay giá trị kinh tế.'],'Holding vàng và định giá đúng compatibility; không money event từ khai báo.','REQ-GOLD-01/02 / AC-05/35','BR-15/16/18/40');
uc(3,'UC-HOLD-01','Cập nhật số lượng, giá vốn và lịch sử tài sản','Chủ workspace','Phản ánh thay đổi holding mà không nhầm với thay đổi giá.','Chọn Cập nhật holding.','Holding thuộc owner, có version và căn cứ ngày/lý do.',[
'Hệ thống hiển thị quantity/cost/history hiện tại.','Người dùng chọn khai báo bổ sung, sửa lượng/cost hoặc nghiệp vụ mua có thanh toán.','Hệ thống xem trước phần thay đổi và phân biệt declaration với purchase.','Người dùng xác nhận khai báo/sửa hợp lệ; mua có đủ căn cứ đi qua UC-BUY-01.','Hệ thống lưu movement/history và tính lại valuation theo quote thích hợp.'
],['Refresh quote không được thay quantity.','Thiếu căn cứ thanh toán: chỉ ghi khai báo/điều chỉnh có nhãn; không bịa cash movement.'],'Quantity/cost/history cập nhật nhất quán; không double-count cash và tài sản.','REQ-HOLD-01 / AC-10','BR-13/15/17/19/40/46');
uc(3,'UC-BUY-01','Liên kết mua tài sản với tài khoản thanh toán','Chủ workspace','Ghi đồng thời lượng mua và tiền thanh toán.','Trong UC-HOLD-01, chọn Mua tài sản.','Có asset identity, tài khoản tiền active và căn cứ giao dịch.',[
'Người dùng nhập quantity, đơn giá, ngày, phí và tài khoản trả tiền.','Hệ thống kiểm dữ liệu và xem trước movement holding cùng bút toán tiền liên kết.','Người dùng xác nhận; hệ thống ghi cash/holding/history trong cùng transaction.','Hệ thống hiện liên kết hai phía và giá vốn theo chính sách.'
],['Không đủ dữ liệu: không tạo giao dịch mua giả từ khai báo.','Một phần ghi thất bại: rollback toàn bộ; timeout kiểm operation cũ.'],'Mua có liên kết atomic một lần; không coi khoản đầu tư là chi sinh hoạt.','Refinement REQ-HOLD-01 / AC-10','BR-13/17/46');
uc(3,'UC-PRICE-01','Đồng bộ giá thị trường thủ công hoặc hằng ngày','Chủ workspace; nhà cung cấp giá thị trường','Cập nhật quote có quyền mà không thay lượng nắm giữ.','Owner chọn Cập nhật hoặc bộ lập lịch nội bộ đến kỳ.','Provider/profile/entitlement hợp lệ; quota còn; instrument xác định.',[
'Hệ thống tạo hoặc gộp yêu cầu vào job cùng khóa thị trường/kỳ phù hợp.','Market worker kiểm quyền nguồn, quota và gọi adapter provider.','Hệ thống kiểm market/product/purity/side/unit/currency/time; lưu quote hợp lệ kèm provenance.','Hệ thống tính lại valuation và công bố kết quả từng phần cùng lastAttempt/lastSuccess/quoteAsOf.'
],['Manual trùng daily: gộp job theo policy, không gọi vô hạn.','429/timeout/partial: retry có giới hạn, giữ last-good có nhãn.','Ngày nghỉ: không sửa quoteAsOf thành hôm nay; không tự bịa lịch sử giá.'],'Quote hợp lệ được cập nhật; quantity/cash/income giữ nguyên.','REQ-PRICE-01 / AC-36','BR-18/19/40/41');
uc(3,'UC-REVIEW-02','Kiểm tra chất lượng giá và tài sản','Chủ workspace','Biết valuation nào thiếu, cũ hoặc sai compatibility.','Mở cảnh báo giá/holding hoặc mục Rà soát.','Có quyền đọc holding, quote và provenance.',[
'Hệ thống liệt kê thiếu quote/cost, stale quote, mismatch và nguồn đã ngắt.','Người dùng mở case để xem quantityAsOf, quoteAsOf, profile và căn cứ.','Người dùng chọn sửa profile/khai báo hoặc yêu cầu refresh nguồn đã được phép.','Hệ thống kiểm lại chất lượng và lưu quyết định/căn cứ; chỉ áp dụng dữ liệu hợp lệ.'
],['Không có nguồn đủ quyền: giữ unresolved/unknown.','Refresh thất bại không đổi giá về 0 và không kết luận giá đã mới.'],'Có kết quả kiểm tra/chất lượng rõ; không tự sửa quantity hoặc cash.','REQ-REVIEW-02 / AC-16','BR-15/18/19/40/41');
uc(4,'UC-OVERVIEW-01','Xem tổng quan tài chính, dòng tiền và tài sản','Chủ workspace','Đọc số liệu tổng hợp cùng phạm vi và mức đầy đủ.','Mở Tổng quan.','Có quyền workspace; kỳ và scope xác định.',[
'Người dùng chọn kỳ và phạm vi tài khoản/tài sản.','Hệ thống đọc snapshot nhất quán và tổng hợp tiền, thu–chi, dòng tiền, cơ cấu tài sản.','Hệ thống hiển thị thời điểm, nguồn, phần unknown/incomplete và cảnh báo.','Người dùng có thể mở drill-down, báo cáo hoặc căn cứ của chỉ số.'
],['Không dữ liệu khác lỗi dịch vụ; opening thiếu làm tổng chưa đầy đủ.','Transfer/opening/valuation change không bị cộng vào income.'],'Chỉ đọc, giữ scope/version của số liệu; không thay ledger.','REQ-OVERVIEW-01 / AC-13','BR-01…04/19/24/45');
uc(4,'UC-REPORT-01','Xem báo cáo tài chính theo kỳ','Chủ workspace','So sánh và phân tích tài chính theo kỳ được chọn.','Chọn báo cáo/tháng/quý/năm/tùy chọn trên Home.','Kỳ và scope hợp lệ; snapshot đọc nhất quán.',[
'Người dùng chọn kỳ, chỉ tiêu và phạm vi.','Hệ thống tính số liệu theo cùng mốc, phân loại và phiên bản.','Hệ thống hiển thị bảng/biểu đồ, kỳ so sánh và coverage.','Người dùng mở drill-down hoặc evidence nếu cần.'
],['Kỳ không có lịch sử đủ: nêu thiếu, không suy thành toàn bộ bằng 0.','Báo cáo là chức năng tích hợp Home; không bắt buộc có màn Reports riêng.'],'Báo cáo có kỳ/scope/version rõ; chỉ đọc.','REQ-REPORT-01 / AC-20','BR-03/19/24/36');
uc(4,'UC-DRILL-01','Phân tích chi tiết và điều chỉnh phạm vi','Chủ workspace','Đi từ chỉ số tới thành phần và giao dịch cấu thành.','Chọn một chỉ số trên Tổng quan hoặc Báo cáo.','Chỉ số gắn snapshot/kỳ/scope; owner có quyền thành phần.',[
'Hệ thống nhận chỉ số và ngữ cảnh từ màn gốc.','Người dùng chọn chiều phân tích hoặc tài khoản/thành phần.','Hệ thống hiện breakdown và danh sách cấu thành với cùng semantics.','Người dùng mở giao dịch/evidence rồi quay lại; ngữ cảnh phân tích được giữ.'
],['Snapshot đã thay đổi: ghi rõ và làm mới, không trộn hai version.','Chuyển scope chỉ ảnh hưởng góc nhìn, không archive hoặc xóa dữ liệu.'],'Có phân tích chi tiết truy được về số tổng; dữ liệu nghiệp vụ không đổi.','REQ-DRILL-01 / AC-14','BR-19/20/24');
uc(4,'UC-INSIGHT-01','Đọc nhận định và phát hiện bất thường','Chủ workspace','Hiểu nhận định có căn cứ và phần còn chưa chắc.','Mở insight/cảnh báo trên Home.','Có snapshot, coverage và bộ quy tắc/phân tích xác định.',[
'Hệ thống phát hiện pattern từ dữ liệu được phép và có nhãn kỳ.','Hệ thống trình bày nhận định, metric, điều kiện và giới hạn coverage.','Người dùng đọc và có thể mở căn cứ hoặc yêu cầu trợ lý giải thích.','Hệ thống giữ liên kết metric về snapshot/evidence.'
],['Thiếu dữ liệu: không khẳng định bất thường chắc chắn.','Insight không tự thay ledger hoặc active plan.'],'Insight có căn cứ và giới hạn; không ghi actual.','REQ-INSIGHT-01 / AC-21','BR-19/25/36');
uc(4,'UC-REVIEW-01','Rà soát nghi vấn dữ liệu tiền','Chủ workspace','Xử lý các nghi vấn theo evidence mà không ghi tiền tùy tiện.','Mở hàng đợi Review.','Case thuộc workspace; có current version.',[
'Hệ thống liệt kê case trùng, chuyển khoản thiếu phía, refund, parse hoặc lệch tiền.','Người dùng chọn case và xem các observation, giao dịch, version và đề xuất.','Hệ thống nêu điều gì chắc chắn, còn thiếu và các quyết định cho phép.','Người dùng chọn xử lý qua UC-RESOLVE-01 hoặc để lại case chưa giải quyết.'
],['Chỉ mở case chưa giải quyết nó.','Không đủ căn cứ: giữ open/deferred; không ép đoán để xóa cảnh báo.'],'Case được đọc/đánh dấu phù hợp; tiền chỉ đổi qua hành động được xác nhận riêng.','REQ-REVIEW-01 / AC-15','BR-09…14/21/42');
uc(4,'UC-RESOLVE-01','Xác nhận quyết định xử lý case','Chủ workspace','Áp dụng khớp/xác nhận/bỏ qua có audit và đúng quyền.','Trong Review, chọn một hành động xử lý.','Case/action/version hợp lệ; đủ evidence và owner confirmation.',[
'Người dùng chọn khớp transfer, xác nhận trùng, ghi hợp lệ hoặc bỏ qua theo loại case.','Hệ thống xem trước thay đổi ledger/liên kết/trạng thái; yêu cầu lý do nếu cần.','Người dùng xác nhận; hệ thống kiểm lại quyền, version và idempotency.','Hệ thống commit atomic tác động được phép cùng history và đóng/cập nhật case.'
],['Hai case cạnh tranh cùng giao dịch: báo conflict và tải lại.','Bỏ qua không xóa raw evidence theo cách tùy tiện; xác nhận duplicate không phát sinh lần ghi tiền thứ hai.'],'Quyết định có trace; chỉ tác động đã duyệt được áp dụng một lần.','Refinement REQ-REVIEW-01 / AC-15','BR-09/12/21/42/46');
uc(4,'UC-EVIDENCE-01','Xem chứng từ và nguồn gốc số liệu','Chủ workspace','Truy nguyên số liệu về dữ liệu/căn cứ hình thành.','Chọn Xem căn cứ trên chỉ số, giao dịch hoặc insight.','Có quyền đọc nguồn trong workspace; liên kết provenance có thể có.',[
'Hệ thống nhận metric/transaction reference và version.','Hệ thống truy các receipt/file/khai báo/quote và parser/manual override liên quan.','Hệ thống trình bày nguồn, thời điểm, trạng thái và lịch sử theo quyền.','Người dùng mở thành phần hoặc quay lại ngữ cảnh trước.'
],['Evidence thiếu/đã hết thời hạn lưu: báo rõ; không bịa reference.','Không hiển thị dữ liệu workspace khác hoặc bí mật credential.'],'Chỉ đọc, truy nguồn có giới hạn rõ; không đổi trạng thái chỉ do xem.','Refinement REQ-TXN-01/OVERVIEW-01/INSIGHT-01','BR-19/21/36');
uc(4,'UC-UX-01','Bật hoặc tắt che thông tin tài chính','Chủ workspace','Che thông tin nhạy cảm khi xem ứng dụng.','Chọn biểu tượng chế độ riêng tư.','Ứng dụng có phiên và preference hiện hành.',[
'Người dùng bật chế độ che.','Hệ thống che amount/quantity ở thẻ, chart, tooltip và accessible text.','Với nội dung AI tự do có số nhạy cảm, hệ thống ẩn phần nội dung theo policy thay vì đoán bằng regex.','Người dùng tắt chế độ; hệ thống phục hồi hiển thị theo quyền.'
],['Giữ ngữ cảnh kỳ/ngày nhưng không rò số qua nhãn hỗ trợ truy cập.','Masking là che giao diện, không thay authorization, mã hóa hoặc giá trị đã lưu.'],'Preference được áp dụng nhất quán; số liệu gốc không đổi.','REQ-UX-01 / AC-17; NFR-12','BR-35; accessibility requirements');
uc(5,'UC-PLAN-01','Lập và điều chỉnh kế hoạch ngân sách','Chủ workspace','Có kế hoạch thu, chi và đầu tư có phiên bản.','Mở Plan; chọn Tạo/Sửa.','Kỳ kế hoạch, workspace, baseline và giả định rõ.',[
'Người dùng nhập các khoản dự kiến, lịch lặp, account, category và liên kết Goal nếu cần.','Hệ thống kiểm ngày, amount, recurrence và phân biệt planned với actual.','Người dùng xem trước tổng hợp và có thể chạy mô phỏng.','Người dùng xác nhận; hệ thống lưu plan/version/history cùng links hợp lệ.'
],['Một khoản kế hoạch có thể không gắn Goal.','Đổi kế hoạch không sinh actual; conflict yêu cầu xem lại version.'],'Active plan được lưu khi owner xác nhận; ledger/tiền hiện có không đổi.','REQ-PLAN-01 / AC-22','BR-26…29/37/38/47');
