const aux=new Set(['UC-CASH-03','UC-BUY-01','UC-DRILL-01','UC-RESOLVE-01','UC-EVIDENCE-01','UC-GOAL-03','UC-FORECAST-01','UC-DRAFT-APPLY-01','UC-INGEST-03']);
const wrap=(s,max=31)=>{const words=s.split(' '),lines=[];let line='';for(const w of words){if(line&&`${line} ${w}`.length>max){lines.push(line);line=w;}else line=line?`${line} ${w}`:w;}if(line)lines.push(line);return lines;};
function textLines(x,y,lines,size=18,color='#20334f',weight=400){return `<text x="${x}" y="${y}" text-anchor="middle" fill="${color}" font-size="${size}" font-weight="${weight}">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?size*1.28:0}">${esc(l)}</tspan>`).join('')}</text>`;}
function actor(x,y,name,color='#31589f'){return `<g stroke="${color}" stroke-width="2.7" fill="none"><circle cx="${x}" cy="${y-50}" r="17"/><path d="M${x},${y-33}v62m-30,-42h60m-30,42l-26,42m26,-42l26,42"/></g>${textLines(x,y+94,wrap(name,20),16,color,600)}`;}
function ellipse(c,x,y,rx=225,ry=53){const color=c.group===7?'#a97419':c.group===6?'#884cc0':'#3566aa';const lines=wrap(c.name,32);return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" stroke="${color}" stroke-width="2.2" fill="${c.group===7?'#fff9e9':c.group===6?'#faf4ff':'#f1f7ff'}"/>${textLines(x,y-(lines.length*22)/2-4,[c.id],15,color,700)}${textLines(x,y-(lines.length-1)*11+14,lines,18)}`;}
function header(title,w,h){return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M1 1 L9 5 L1 9" fill="none" stroke="context-stroke" stroke-width="1.4"/></marker></defs><rect width="100%" height="100%" fill="white"/><g font-family="Segoe UI, Arial, sans-serif"><rect x="24" y="20" width="${w-48}" height="70" rx="12" fill="#101d35"/><text x="48" y="52" font-size="23" font-weight="700" fill="white">${esc(title)}</text><text x="48" y="77" font-size="15" fill="#bbcbe3">FinWeave · ${title.startsWith('KIẾN TRÚC')?'Architecture view':'UML use case'} · 28/10/2026 · đặc tả và đối chiếu, không chứng nhận nghiệm thu</text>`;}
const end='</g></svg>';
