 if(g===6)right.push({...cases.find(c=>c.id==='UC-SIM-01'),name:'Chạy mô phỏng kịch bản (dùng chung phân hệ 5)'});
 const rows=Math.max(left.length,right.length,4),h=265+rows*137,w=1700,ay=180+rows*137/2;
 const pos=new Map();left.forEach((c,i)=>pos.set(c.id,{x:540,y:215+i*137,c}));right.forEach((c,i)=>pos.set(c.id,{x:1100,y:230+i*190,c}));
 let svg=header(`${g?`PHÂN HỆ ${g}`:'DÙNG CHUNG'} — ${groups[g][0]}`,w,h)+`<rect x="245" y="115" width="1120" height="${h-162}" rx="15" fill="#fbfcff" stroke="#4b5563" stroke-width="1.8"/><text x="270" y="148" font-size="17" font-weight="600">FinWeave — ${esc(groups[g][0])}</text>`;
 const primary=g===7?'Quản trị viên ứng dụng':g===0?'Người dùng / Chủ workspace':'Chủ workspace';
 svg+=actor(100,ay,primary,g===7?'#a97419':'#31589f');
 for(const c of left){const p=pos.get(c.id);svg+=`<path d="M150 ${ay} L${p.x-225} ${p.y}" stroke="#4b5563" fill="none" stroke-width="1.6"/>`;}
 // Optional subgoals retain the owner association by using a second visual occurrence of the SAME actor.
 const ownerRight=right.filter(c=>c.id!=='UC-FORECAST-01'&&c.id!=='UC-INGEST-03'&&c.id!=='UC-SIM-01');
 if(ownerRight.length){const sideY=g===6?650:ownerRight.reduce((sum,c)=>sum+pos.get(c.id).y,0)/ownerRight.length;svg+=actor(1510,sideY,primary+' (cùng vai trò)',g===7?'#a97419':'#31589f');for(const c of ownerRight){const p=pos.get(c.id);svg+=`<path d="M1460 ${sideY} L${p.x+225} ${p.y}" stroke="#4b5563" fill="none" stroke-width="1.6"/>`;}}
 if(g===2){const p=pos.get('UC-INGEST-03'),capture=pos.get('UC-CAPTURE-01');svg+=actor(1510,220,'Android OS / ứng dụng nguồn');svg+=`<path d="M1460 220 L1325 ${p.y}" stroke="#4b5563" fill="none" stroke-width="1.6"/><path d="M1460 220 H1390 V${capture.y} H765" stroke="#4b5563" fill="none" stroke-width="1.6"/>`;}
 if(g===3){const p=pos.get('UC-PRICE-01');svg+=actor(1510,p.y,'Nhà cung cấp giá');svg+=`<path d="M1460 ${p.y} L${p.x+225} ${p.y}" stroke="#4b5563" fill="none" stroke-width="1.6"/>`;}
 if(g===6){svg+=actor(1510,170,'Dịch vụ mô hình AI (khi bật)','#884cc0');svg+=`<path d="M1460 170 H1390 V162 H800 L740 190" stroke="#884cc0" fill="none" stroke-width="1.5"/>`;for(const id of ['UC-AGENT-01','UC-AGENT-02']){const p=pos.get(id);svg+=`<path d="M1460 170 H1390 V${p.y} H765" stroke="#884cc0" fill="none" stroke-width="1.5"/>`;}}
 const local=relations.filter(([a,b])=>pos.has(a)&&pos.has(b));
 for(let i=0;i<local.length;i++){const [a,b,t]=local[i],p=pos.get(a),q=pos.get(b),same=p.x===q.x;let path,lx,ly;
  if(same){const xx=p.x+245+(i%3)*25;path=`M${p.x+220} ${p.y} C${xx+110} ${p.y},${xx+110} ${q.y},${q.x+220} ${q.y}`;lx=xx+67;ly=(p.y+q.y)/2;}
  else{const from=p.x<q.x?p.x+225:p.x-225,to=p.x<q.x?q.x-225:q.x+225;path=`M${from} ${p.y} C${(from+to)/2} ${p.y},${(from+to)/2} ${q.y},${to} ${q.y}`;lx=(from+to)/2;ly=(p.y+q.y)/2-9;}
  const color=t==='include'?'#177c76':'#a66d16';svg+=`<path d="${path}" stroke="${color}" stroke-width="1.7" stroke-dasharray="7 5" fill="none" marker-end="url(#arrow)"/><rect x="${lx-54}" y="${ly-17}" width="108" height="25" rx="5" fill="white" stroke="${color}" stroke-width=".7"/>${textLines(lx,ly,[`«${t}»`],15,color)}`;
 }
 for(const p of pos.values())svg+=ellipse(p.c,p.x,p.y);
 svg+=`<text x="265" y="${h-24}" font-size="14" fill="#52637b">Đường liền: liên kết tác nhân · Nét đứt: include/extend · Điều kiện và extension point: xem bảng quan hệ trong đặc tả</text>`+end;
 await put(`diagrams/${groups[g][1]}.svg`,svg);
